// Writes js/woodcut/gen/lyrics.js from source/lines.json (the timed contract). Run from the project folder:
//   node js/woodcut/make-lyrics.mjs
// The output quotes the lyric, so it lives under gen/ (gitignored). Never edit the generated file by hand.
import fs from 'fs';
const d = JSON.parse(fs.readFileSync('source/lines.json', 'utf8'));
const T1 = 34.416667;
const lines = d.lines.filter(l => l.s < T1).map(l => ({ i: l.i, text: l.text, s: l.s, e: l.e, words: l.words.map(w => ({ w: w.w, s: w.s, e: w.e })) }));
for (const l of lines) if (l.words.map(w => w.w).join(' ') !== l.text) throw new Error('word list does not rebuild line ' + l.i);
fs.mkdirSync('js/woodcut/gen', { recursive: true });
fs.writeFileSync('js/woodcut/gen/lyrics.js', '// GENERATED by make-lyrics.mjs from source/lines.json (' + d.sha256.slice(0, 12) + '). Do not edit.\nconst LYR = ' + JSON.stringify(lines) + ';\n');
console.log(lines.length, 'lines');
